/// <reference types="vitest/config" />
import { fileURLToPath } from 'node:url';
import { getViteConfig } from 'astro/config';

// Astro's Vite config, so tests can import and render real .astro components
// (test/fixtures) with the Container API, exactly as the preview server does.
export default getViteConfig(
  {
    resolve: {
      alias: {
        // Generated by the integration during a real build; tests get a
        // double they can fill in (test/fixtures/virtual-preview-site.ts).
        'virtual:preview-site': fileURLToPath(
          new URL('./test/fixtures/virtual-preview-site.ts', import.meta.url),
        ),
      },
    },
    test: {
      include: ['src/**/*.test.ts', 'test-editor/**/*.test.ts'],
      restoreMocks: true,
      environmentOptions: {
        happyDOM: {
          // The editor sets iframe.src; never let the test DOM fetch it.
          settings: {
            disableIframePageLoading: true,
            handleDisabledFileLoadingAsSuccess: true,
          },
        },
      },
      coverage: {
        provider: 'v8',
        reporter: ['text', 'html'],
        // Floors a few points under the 2026-10-29 baseline (99.2 / 97.2 / 99.3 / 99.1).
        // A ratchet: raise when the score rises; lower only with a reason in the commit.
        thresholds: { lines: 96, functions: 96, branches: 94, statements: 96 },
        include: ['src/**', 'test-editor/**'],
        exclude: [
          '**/*.test.ts',
          '**/*.d.ts',
          'src/types.ts',
          // Glue scripts with top-level side effects: covered by the
          // end-to-end suite, not unit tests.
          'src/build.ts',
          'src/start.ts',
          'test-editor/editor.astro',
          // Import virtual modules only a real build can load (or are bound
          // to them in a line or two): covered by the end-to-end suite.
          'src/render-route.ts',
          'src/validate-route.ts',
          'src/warmup-route.ts',
          'src/dev/documents-route.ts',
          'src/render/runtime.ts',
          'src/overlay/content-shim.ts',
          'src/overlay/markdown-instance.ts',
          // Run as a bundled copy by loadCmsCollections (tested in
          // config-bundle.test.ts), so v8 can't attribute it to this file.
          'src/schema/stubs-flavor1.ts',
        ],
      },
    },
  },
  // Astro config for the test run: no site, just the compiler.
  { root: fileURLToPath(new URL('.', import.meta.url)), logLevel: 'error' },
);
